# brute: all prefixes of name
for i in range(len(name)+1):
    for enc in ('utf-8','utf-16-le'):
        if (zlib.crc32(name[:i].encode(enc))&0xffffffff)==target: print("PREFIX MATCH", i, repr(name[:i]), enc)
# suffixes
for i in range(len(name)+1):
    for enc in ('utf-8','utf-16-le'):
        if (zlib.crc32(name[i:].encode(enc))&0xffffffff)==target: print("SUFFIX MATCH", i, repr(name[i:]), enc)
print("done")
